func OAuthMethods() []string {
	var out []string
	seen := map[string]bool{}
	for _, op := range Operations {
		if op.NSID != "" && !seen[op.NSID] {
			out = append(out, op.NSID)
			seen[op.NSID] = true
		}
	}
	return out
}
